// One-time, identity-preserving review. The audit is captured BEFORE applying edits.
import fs from 'node:fs';
import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import {load} from './lib/load-typescript-data.mjs';
import {getPriorMeaning} from './lib/translation-prompt-baseline.mjs';
const {QUESTIONS}=load('src/data/questions.ts');
const {getQuestionMeaning}=load('src/data/questionMeaning.ts');
const file='src/data/translationBattlePrompts.json';
const entries=JSON.parse(fs.readFileSync(file,'utf8'));
const auditFile='docs/pre2-level2-prompt-review-2026-10-18.json';
assert.ok(!fs.existsSync(auditFile),'Do not overwrite the original before/after audit');
const edits=new Map();
const labels=s=>s?s.split(';').map(v=>{const [text,note]=v.split('|');assert.ok(text&&note);return {text,note};}):[];
function edit(text,meaning,alternatives='',contrasts='',reason='意味が重なる自然な別表現を示し、和訳だけで一意に決まるという誤解を減らす。'){
 assert.ok(!edits.has(text));edits.set(text,{meaning,alternatives:labels(alternatives),contrasts:labels(contrasts),formNote:'',reason});
}
