const snapshot=q=>{const e=entries.find(e=>e.course==='EikenPre2'&&e.level===2&&e.text===q.text&&e.translation===q.translation&&(e.exampleEn??'')===(q.exampleEn??''));return {meaning:getQuestionMeaning(q,'EikenPre2'),alternatives:e?.alternatives??[],contrasts:e?.contrasts??[],formNote:e?.formNote??''};};
const rows=QUESTIONS.EikenPre2[2].map(q=>{
 const before=snapshot(q),change=edits.get(q.text);if(change){
  let e=entries.find(e=>e.course==='EikenPre2'&&e.level===2&&e.text===q.text);
  if(!e){e={course:'EikenPre2',level:2,text:q.text,translation:q.translation,...(q.exampleEn?{exampleEn:q.exampleEn}:{}),previousMeaning:getPriorMeaning(q,'EikenPre2')};entries.push(e);}
  Object.assign(e,change);
 }
 return {text:q.text,translation:q.translation,exampleEn:q.exampleEn,before,after:change?{meaning:change.meaning,alternatives:change.alternatives,contrasts:change.contrasts,formNote:change.formNote}:before,changed:!!change,reason:change?.reason??'既存の意味・文型・類義表現を確認し、今回の変更は不要と判断。'};
});
assert.equal(rows.filter(r=>r.changed).length,edits.size);
const hash=v=>createHash('sha256').update(JSON.stringify(v)).digest('hex');
const audit={date:'2026-10-18',course:'EikenPre2',level:2,reviewed:rows.length,changed:edits.size,questionsSha256:hash(QUESTIONS),unrelatedPromptsSha256:hash(entries.filter(e=>e.course!=='EikenPre2'||e.level!==2)),rows};
fs.writeFileSync(auditFile,JSON.stringify(audit,null,2)+'\n');
fs.writeFileSync(file,JSON.stringify(entries,null,2)+'\n');
console.log({reviewed:rows.length,changed:edits.size});
